globalThis.makeSubjectEdition = function (meta, rows) {
  const {subject, year, grade, contest, letters, tasksFile, answersFile, language} = meta;
  const folder = 'assets/' + subject + '/' + year + '/';
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(row => {
    const {title, question, choices, figure, figures, optionFigures, steps, context, audio, numericAnswer} = row;
    const condition = figures?.length ? {items: figures} : figure;
    const options = choices.map((text, i) => {
      const image = optionFigures?.[i];
      if (!image) return {text};
      return {text: row.showOptionText ? text : '', image: image.src,
        description: row.showOptionText ? text + '. ' + image.alt : image.alt,
        ...(image.detailSrc ? {detailSrc: image.detailSrc} : {}),
        pixelWidth: image.width, pixelHeight: image.height};
    });
    return {
      title, question, choices, language, context, guided: true, hideIntroText: true,
      skill: contest, answer: row.answer ?? null,
      points: row.points ?? meta.points,
      ...(row.adaptation ? {questionNote: row.adaptation} : {}),
      ...(row.number ? {number: row.number} : {}),
      ...(Number.isInteger(numericAnswer) ? {numericAnswer} : {}),
      ...(audio ? {audio: folder + (meta.listeningFile ?? 'listening.mp3')} : {}),
      ...(condition || optionFigures ? {choiceLayout: {condition, options},
        choiceImages: options.map(option => option.image),
        ...(condition?.src ? {conditionImage: condition.src, conditionAlt: condition.alt} : {})} : {}),
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ...steps.map((explanation, index) => index === steps.length - 1
          ? ['Проверка', 'Проверка', explanation]
          : [index ? 'Шаг ' + (index + 1) : 'Первый шаг', 'Рассуждение', explanation]),
        ['Ответ', 'Ответ', ''],
      ],
    };
  });
  for (const group of meta.matchingGroups ?? []) {
    const parts = lessons.slice(group.start - 1, group.start - 1 + group.count);
    if (parts.length !== group.count || parts.some(part => !part.conditionImage ||
        JSON.stringify(part.choices) !== JSON.stringify(parts[0].choices))) throw new Error('Incomplete matching group ' + group.title);
    const steps = [
      ['Выбор', 'Условие задачи', ''],
      ...parts.map((part, index) => ['Рисунок ' + (index + 1), part.title,
        part.steps.slice(1, -1).map(step => step[2]).join(' ')]),
      ['Ответ', 'Все пары', ''],
    ];
    for (const part of parts) Object.assign(part, {matching: group, title: group.title, question: group.question, steps});
  }
  return {
    id: [year, subject, meta.session, grade, meta.editionSuffix].filter(Boolean).join('-'), year, grades,
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы') + (meta.sessionTitle ? ' · ' + meta.sessionTitle : '') + (meta.editionLabel ? ' · ' + meta.editionLabel : ''),
    ...(meta.sections ? {sections: meta.sections} : {}),
    ...(meta.titleLanguage ? {titleLanguage: meta.titleLanguage} : {}),
    subject, answerLetters: [...letters], sources: {
      contest, tasksUrl: folder + tasksFile, answersUrl: folder + answersFile,
      ...(meta.reviewedKey ? {reviewedKey: true} : {}),
    },
    lessons, scenes: lessons.map(() => () => ''),
  };
};

const edition = globalThis.makeSubjectEdition({"subject":"kit","year":2022,"grade":"6-7","contest":"КИТ","letters":"АБВГ","count":21,"language":"ru","points":3,"tasksFile":"6-7.pdf","answersFile":"reviewed-6-7.pdf","sections":[{"start":1,"title":"2 балла · № 1–8"},{"start":9,"title":"3 балла · № 9–16"},{"start":17,"title":"4 балла · № 17–18"},{"start":19,"title":"Числовой ответ · № 19–21"}],"reviewedKey":true}, [{"title":"Латинское слово","question":"Cursiva с латыни переводится как «беглый». Переведи с латинского языка слово cursor.","choices":["бегун","красный","сорить","курица"],"points":2,"steps":["У слов cursiva и cursor общий латинский корень, связанный с бегом и движением.","Cursor — тот, кто бежит, то есть бегун. Компьютерный курсор тоже перемещается по экрану."],"answer":0},{"title":"Время на часах","question":"Какие часы показывают без двадцати четыре?","choices":["Часы А","Часы Б","Часы В","Часы Г"],"points":2,"steps":["«Без двадцати четыре» значит, что до четырёх осталось двадцать минут. Сейчас 3:40 или 15:40. Минутная стрелка указывает на 8, потому что 8 × 5 = 40.","Короткая стрелка должна стоять между 3 и 4, ближе к 4. Так стрелки стоят на часах В."],"answer":2,"optionFigures":[{"src":"assets/kit/2022/4-5-02-a.webp","alt":"Минутная стрелка у 4, часовая между 8 и 9","width":134,"height":136},{"src":"assets/kit/2022/4-5-02-b.webp","alt":"Минутная стрелка у 12, часовая у 10","width":134,"height":134},{"src":"assets/kit/2022/4-5-02-c.webp","alt":"Минутная стрелка у 8, часовая между 3 и 4","width":142,"height":138},{"src":"assets/kit/2022/4-5-02-d.webp","alt":"Минутная стрелка у 6, часовая между 1 и 2","width":138,"height":138}]},{"title":"Почтальон на маршруте","question":"Почтальон разносит почту. Что он принесёт в квартиру 2?","choices":["письмо","открытку","журнал","газету"],"points":2,"steps":["Найди квартиру 2 справа. В неё приходит наклонная стрелка сверху слева.","Эта стрелка отходит от «письмо», как и горизонтальная стрелка к квартире 1. В квартиру 2 принесут письмо."],"answer":0,"figure":{"src":"assets/kit/2022/6-7-03.webp","alt":"Письмо стрелками соединено с квартирами 1 и 2, открытка, журнал и газета — с квартирой 3.","width":238,"height":100}},{"title":"Зачем скрывают пароль","question":"При авторизации в социальных сетях предлагается ввести логин и пароль. Пароль отображается в виде точек или звёздочек. Зачем?","choices":["так удобнее","для обеспечения безопасности","чтобы запутать","точки или звёздочки — это и есть пароль"],"points":2,"steps":["Точки показывают, что символы введены, но скрывают сами буквы и цифры.","Так сложнее подсмотреть пароль через плечо или увидеть его на записи экрана. Поэтому ответ Б — для обеспечения безопасности."],"answer":1},{"title":"Устройства в паре","question":"Какое устройство обычно используют парами?","choices":["Ноутбук","Принтер","Мышь","Колонка"],"points":2,"steps":["Ноутбуком, принтером и мышью обычно пользуются по отдельности.","Колонки часто ставят слева и справа. Две колонки позволяют слышать разные каналы стереозвука."],"answer":3,"optionFigures":[{"src":"assets/kit/2022/4-5-05-a.webp","alt":"Ноутбук с открытой крышкой","width":162,"height":124},{"src":"assets/kit/2022/4-5-05-b.webp","alt":"Принтер","width":160,"height":114},{"src":"assets/kit/2022/4-5-05-c.webp","alt":"Компьютерная мышь","width":120,"height":106},{"src":"assets/kit/2022/4-5-05-d.webp","alt":"Одна акустическая колонка","width":82,"height":124}]},{"title":"Носитель для граммофона","question":"Как назывался носитель информации для устройства, изображённого справа?","choices":["грампластинка","жернова","блин","CD-диск"],"points":2,"steps":["На рисунке граммофон. Он вращает диск, а игла движется по его звуковой дорожке.","Диск с записанной дорожкой, который можно воспроизвести на граммофоне, называется грампластинкой."],"answer":0,"figure":{"src":"assets/kit/2022/6-7-06.webp","alt":"Граммофон с рупором и горизонтальной площадкой для диска.","width":144,"height":176}},{"title":"Картинка после правки","question":"Саша, изучая возможности графического редактора, изменил одну из характеристик картинки слева. В итоге получилось то, что вы видите на картинке справа. Какой из параметров Саша сильно уменьшил?","choices":["яркость","глубина цвета","расширение","разрешение"],"points":2,"steps":["На правой картинке видны крупные квадратные пиксели. Мелкие детали слева передать этими пикселями не получается.","При уменьшении разрешения редактор описывает картинку меньшим числом пикселей, даже если она занимает то же место на экране. Изменение яркости или глубины цвета не уменьшает число пикселей."],"answer":3,"figure":{"src":"assets/kit/2022/6-7-07.webp","alt":"Слева чёткий рисунок улыбающегося кита с ноутбуком. Справа его силуэт сделан из крупных квадратных пикселей.","width":290,"height":126}},{"title":"Маршрут через города","question":"Выбери туристическую карту, по которой можно пройти от A до F, посетив при этом наибольшее количество городов.","choices":["Карта А","Карта Б","Карта В","Карта Г"],"points":2,"steps":["На карте А из A нельзя выйти по стрелкам. На карте Б путь из A через B заканчивается в C.","На карте В до F можно добраться через B и C, посетив четыре города. На карте Г маршрут A → D → E → B → C → F охватывает все шесть."],"answer":3,"optionFigures":[{"src":"assets/kit/2022/4-5-08-a.webp","alt":"B → A, B → C, B → E, C → F, F → E, E → D, D → A","width":160,"height":108},{"src":"assets/kit/2022/4-5-08-b.webp","alt":"A → B → C, E → D, E → F, D → A, E → B, F → C","width":158,"height":108},{"src":"assets/kit/2022/4-5-08-c.webp","alt":"A → B → C, A → D, B → E, C → F, F → E, E → D","width":158,"height":108},{"src":"assets/kit/2022/4-5-08-d.webp","alt":"A → B → C, A → D, E → B, C → F, D → E → F","width":158,"height":108}]},{"title":"Как заплатить за ручку","question":"У Васи много монет по 1 рублю и по 5 рублей. Сколькими способами он может заплатить за ручку ровно 6 рублей?","choices":["1","2","3","4"],"points":3,"steps":["Если взять одну пятирублёвую монету, останется добавить 1 рубль. Две пятирублёвые уже дают больше 6.","Без пятирублёвых монет нужны шесть монет по рублю. Итого два способа."],"answer":1},{"title":"Деталь ЭВМ","question":"Как выглядел транзистор транзисторного ЭВМ?","choices":["Разъём питания","Транзистор","Свеча зажигания","Керосиновая лампа"],"points":3,"steps":["Транзистор — отдельная электронная деталь. Тремя выводами на фото её подключают к схеме, чтобы один сигнал управлял другим.","Такой корпус с тремя выводами виден на фото Б. Разъём А соединяет кабель с устройством, свеча В даёт искру, лампа Г освещает комнату."],"answer":1,"optionFigures":[{"src":"assets/kit/2022/6-7-10-a.webp","alt":"Разъём на кабеле питания","width":116,"height":162},{"src":"assets/kit/2022/6-7-10-b.webp","alt":"Металлический корпус с тремя выводами","width":108,"height":161},{"src":"assets/kit/2022/6-7-10-c.webp","alt":"Автомобильная свеча зажигания","width":54,"height":162},{"src":"assets/kit/2022/6-7-10-d.webp","alt":"Керосиновая лампа","width":60,"height":162}]},{"title":"Единица размера шрифта","question":"Начав работу в текстовом редакторе, Петя в поле «Размер шрифта» выбрал «14». В подавляющем числе случаев по умолчанию имеется в виду…","choices":["14 мм","14 ярдов","14 пунктов","14 дюймов"],"points":3,"steps":["Размер шрифта в текстовых редакторах обычно записывают в типографских пунктах. В англоязычном интерфейсе единица обозначается pt.","Запись «14» здесь означает 14 пунктов. В компьютерной типографике один пункт равен 1/72 дюйма."],"answer":2},{"title":"Имя учёного","question":"Какой термин связан с именем учёного, изображённого справа?","choices":["модем","цикл","алгоритм","компьютер"],"points":3,"steps":["На марке подписано имя Мухаммада аль-Хорезми. Его трактат познакомил европейских читателей с вычислениями в позиционной системе.","Латинизированная форма имени аль-Хорезми дала слово «алгоритм». Сейчас так называют порядок действий для решения задачи."],"answer":2,"figure":{"src":"assets/kit/2022/4-5-10.webp","alt":"Марка с портретом и подписью «Мухаммад аль-Хорезми».","width":162,"height":224}},{"title":"Старший из братьев","question":"В семье пять братьев, про которых известно, что Вася старше Коли, Саша младше Серёжи, Вася старше Володи и Серёжа младше Володи. Старшего брата в семье зовут…","choices":["Вася","Володя","Коля","Саша"],"points":3,"steps":["По данным условия Вася старше Володи, Володя старше Серёжи, а Серёжа старше Саши.","Мы также знаем, что Вася старше Коли. Он старше каждого из четырёх братьев."],"answer":0},{"title":"Дата с двумя прочтениями","question":"В некоторых странах (например, в России) 4 февраля записывают как 04.02, а в некоторых — как 02.04. Сколько дней в году невозможно идентифицировать однозначно, если не знать, какая система записи используется?","choices":["12","132","144","365"],"points":3,"steps":["Число больше 12 может обозначать только день. Два прочтения возможны, когда обе части записи от 1 до 12.","Всего таких записей 12 × 12 = 144. Когда обе части равны, порядок ничего не меняет. Таких записей 12, от 01.01 до 12.12.","Остаётся 144 − 12 = 132 двусмысленные записи. Каждая соответствует своему дню при фиксированном порядке записи."],"answer":1},{"title":"Робот убирает комнату","question":"Робот-пылесос убирает комнату по спирали. На каждом шаге он пробует соседние клетки в таком порядке: слева по ходу движения, прямо и справа. Он переходит в первую свободную клетку, которую ещё не убирал, и поворачивается в сторону движения. Если таких клеток нет, он останавливается. Сколько свободных клеток робот не уберёт, если начнёт с поля А12 и поедет вправо?","choices":["0","8","12","4"],"points":3,"steps":["Пройди из А12 вправо до С12, затем вниз до С1 и влево до О1. Дальше робот огибает чёрное препятствие, оставляя его слева, и доходит до А1.","От А1 он поднимается до А11 и начинает следующий виток, оставляя прежний путь слева. На каждом шаге сначала проверь клетку слева, потом клетку прямо и наконец справа.","Последний ход ведёт в О9, где не осталось свободного соседа. Свободными остались четыре клетки в ряду 7 и четыре в ряду 8, в столбцах Г, Д, Е и Ж. Всего 8."],"answer":1,"figure":{"src":"assets/kit/2022/4-5-15.webp","alt":"Сетка из 17 столбцов А, Б, В, Г, Д, Е, Ж, З, И, К, Л, М, Н, О, П, Р, С и 12 рядов, пронумерованных снизу вверх. Препятствие занимает столбцы Д–Н в рядах 1–3 и Л–Н в рядах 4–5.","width":440,"height":316},"reviewedEdition":true},{"title":"Экран без диагоналей","question":"Каждая ячейка экрана калькулятора отображает одну цифру при помощи трёх горизонтальных, четырёх вертикальных и двух диагональных перекладин, как показано на рисунке. Сколько всего различных цифр можно определить в ячейке однозначно, если перегорят обе диагональные перекладины этой ячейки?","choices":["6","7","8","10"],"points":3,"steps":["Убери диагональные чёрные штрихи и сгруппируй цифры по горизонтальным перекладинам. Совпадают группы 0 и 2, 3 и 9, 5 и 8. У цифр 1, 4, 6 и 7 свой набор горизонталей.","В каждой паре есть различие по вертикали. У 0 горят все четыре вертикали, у 2 — только верхняя правая. У 9 есть верхняя левая вертикаль, которой нет у 3. У 8 есть нижняя левая вертикаль, которой нет у 5.","Оставшихся штрихов хватит, чтобы узнать любую из десяти цифр."],"answer":3,"figure":{"src":"assets/kit/2022/display-segments.svg","alt":"Десять наборов от 0 до 9. В каждом тонкие линии обозначают выключенные, толстые — включённые перекладины. Потухшие диагонали мысленно уберите.","width":393,"height":63}},{"title":"Снятие денег в банкомате","question":"На счёте Ка-Ака было 2000 пиастров. Он дважды снял одну и ту же сумму, набирая её в банкомате как #, æ, Ω. Эти три знака обозначают разные цифры десятичной системы планеты Туя. Попытка снять ещё 27 пиастров не удалась, потому что денег осталось меньше 27. Какую цифру обозначает Ω?","choices":["6","7","3","9"],"points":4,"steps":["Два одинаковых снятия прошли, поэтому одна сумма не больше 1000. После них осталось меньше 27. Значит, всего сняли больше 1973 пиастров, а каждое снятие составляло не меньше 987.","Сумму ввели тремя разными цифрами, поэтому 1000 отпадает. Среди чисел от 987 до 999 только 987 состоит из трёх разных цифр.","Последний знак Ω обозначает 7. После двух снятий остаётся 2000 − 2 × 987 = 26, так что снять ещё 27 нельзя."],"answer":1,"reviewedEdition":true},{"title":"Цепочка замен букв","question":"Каждый из четырёх школьников, играя в глухой телефон, в передаваемом слове менял одну букву на соседнюю по алфавиту. На выходе получилось слово пень. Каким могло быть исходное слово, предложенное им?","choices":["тень","лень","конь","пена"],"points":4,"steps":["В слове «лень» первую букву можно сдвинуть четыре раза: Л → М → Н → О → П. Остальные буквы остаются прежними.","От Т до П три шага. Если потратить лишний шаг, пришлось бы сдвинуть ещё одну букву или уйти с нужного места. Вернуться сюда можно лишь за чётное число лишних шагов.","От К до П требуется уже пять шагов, а в «конь» нужно изменить и вторую букву. В слове «пена» А и Ь тоже разделяют больше четырёх позиций."],"answer":1},{"title":"Маршрут по трём этажам","question":"Трёхэтажное здание состоит из 25 комнат на каждом этаже. На плане дома тонкой линией обозначены комнаты, между которыми есть дверь, толстой — если двери нет. В доме имеется 5 лестниц (в угловых комнатах и центральной). Войдя в комнату с лестницей, ею пользоваться не обязательно. Коля заходит в левую нижнюю (на схеме) комнату первого этажа, а закончить свой маршрут должен в правой верхней комнате третьего этажа. Чему равно минимальное количество комнат, которые посетит Коля (начальная и конечная комнаты считаются)?","choices":[],"points":4,"steps":["Обозначим столбцы A–E слева направо, ряды 1–5 сверху вниз. Поставь 1 в A5 на первом этаже. Отметь числом 2 все комнаты в одном переходе и продолжай по очереди. Дверь и переход по лестнице на соседний этаж стоят по одному шагу.","При таком обходе впервые отмечаем каждую комнату минимальным счётом посещений. У лестницы E1 получаются 17 на первом этаже, 18 на втором и 19 на третьем. Значит, меньше 19 комнат не хватит.","Вот маршрут с таким счётом. По лестнице A5 поднимись с первого этажа на третий и пройди по его нижнему ряду до E5. Спустись на второй в E5 и иди через E4, E3, D3 до C3.","Из C3 спустись на первый и пройди C2 → D2 → D1 → E1. Поднимись по лестнице E1 на третий этаж. С учётом начала и конца пройдено 19 комнат."],"numericAnswer":19,"figure":{"src":"assets/kit/2022/6-7-19.webp","alt":"Три плана по 5×5 комнат. Столбцы A–E слева направо, строки 1–5 сверху вниз. Лестницы во всех углах и в центре. Толстые вертикальные границы: этаж 1, C1/D1, A2/B2, D2/E2, A3/B3, D3/E3, D4/E4, B5/C5; этаж 2, C1/D1, A2/B2, A3/B3, B3/C3, D4/E4, D5/E5; этаж 3, C1/D1, D1/E1, A2/B2, D2/E2, A3/B3, C3/D3, A4/B4, C4/D4, D4/E4. Толстые горизонтальные границы: этаж 1, B1/B2, C1/C2, E1/E2, B3/B4, C3/C4, D3/D4, C4/C5, D4/D5; этаж 2, B1/B2, C1/C2, C2/C3, D2/D3, E2/E3, B3/B4, C3/C4, D3/D4; этаж 3, B1/B2, C1/C2, D2/D3, E3/E4, A4/A5, B4/B5, C4/C5, D4/D5.","width":740,"height":248}},{"title":"Кто говорит правду","question":"За столом переговоров собрались 6 человек. Часть из них говорит только правду, а часть — всегда лжёт. В результате каждый заявил остальным: «Все вы — лжецы». Сколько человек, говорящих правду, сидит за столом?","choices":[],"points":4,"steps":["Если бы все лгали, у каждого из шести фраза «Все вы — лжецы» была бы верной. Значит, кто-то говорит правду.","Как только один говорит правду, остальные пять по его верному утверждению лгут. Их фраза действительно неверна: среди остальных есть тот, кто говорит правду."],"numericAnswer":1},{"title":"Кольца на трёх стержнях","question":"Даны три различных по размеру кольца и три стержня. За один ход можно перемещать одно кольцо с одного стержня на другой. При этом можно ставить только меньшее кольцо на большее. Сначала башня построена на одном из стержней в порядке от большего кольца внизу до меньшего наверху. За какое наименьшее количество ходов можно переместить кольца с одного стержня на другой?","choices":[],"points":4,"steps":["Чтобы передвинуть большое кольцо на свободный стержень, сначала собери два маленьких на другом стержне. Для этого необходимы три хода: малое в сторону, среднее на нужный стержень, малое поверх среднего.","Перенеси большое кольцо одним ходом. Затем теми же тремя ходами собери два маленьких на большом.","Меньше невозможно: перед ходом большого надо переместить оба маленьких, а после его хода оба нужно снова переставить друг на друга. Эти операции стоят по три хода. Итого 3 + 1 + 3 = 7."],"numericAnswer":7}]);
